<script setup lang="ts">import {onMounted,ref} from 'vue';import {supabase} from '@/lib/supabase';import {useAuth} from '@/stores/auth'
const auth=useAuth(),form=ref({username:'',phone:'',email:'',about:''}),error=ref(''),success=ref(''),busy=ref(false)
onMounted(async()=>{const id=auth.profile?.id;if(!id)return;const {data,error:e}=await supabase.from('profiles').select('username,phone,email,about').eq('id',id).single();if(e)error.value=e.message;else form.value={username:data.username,phone:data.phone??'',email:data.email??'',about:data.about??''}})
async function save(){busy.value=true;error.value='';success.value='';const {error:e}=await supabase.from('profiles').update({phone:form.value.phone||null,email:form.value.email||null,about:form.value.about||null}).eq('id',auth.profile!.id);if(e)error.value=e.message;else success.value='Account details updated.';busy.value=false}
</script><template><section class="page-wrap"><div class="page-heading"><div><h1>My account</h1><p>Update your contact details and profile information.</p></div></div><form class="panel" style="max-width:600px;display:grid;gap:13px" @submit.prevent="save"><label>Username<input :value="form.username" class="control" disabled></label><label>Phone<input v-model="form.phone" class="control"></label><label>Email<input v-model="form.email" type="email" class="control"></label><label>About<textarea v-model="form.about" class="control" rows="4"/></label><p v-if="error" class="alert">{{error}}</p><p v-if="success" class="success">{{success}}</p><button class="btn primary" :disabled="busy">{{busy?'Saving…':'Save changes'}}</button></form></section></template>
